using System;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using C2=CrabCityDensityR2;

public static class City2Data {
 [Serializable] public class Shard {public int shard;public float[] center,size;public float massKgSuggestion;}
 [Serializable] public class Proposal {public string asset,material;public float massKgSuggestion,normalizedImpulseThresholdSuggestion,maxPostBreakSpeedFractionSuggestion;public Shard[] shards;}
 [Serializable] class Proposals {public Proposal[] assets;}
 #if UNITY_EDITOR
 public static bool ReviewUseDenseLayout;
#endif
 public static bool UseRouteR29=true;static C2.CityDensityPack.Layout routeR29;public static bool UseProgressionR12;static C2.CityDensityPack.Layout routeR12;public static bool UseRouteBlockoutR11;static C2.CityDensityPack.Layout farRouteR11;public static bool UseFarWorldR10;static C2.CityDensityPack.Layout farWorldR10;public static bool UseWorldArtR9;public static bool UseAtriumRoute;static C2.CityDensityPack.Layout atrium;public static bool UseCoreLayout;static C2.CityDensityPack.Layout core;
 static C2.CityDensityPack.Geometry geometry;static C2.CityDensityPack.Layout dense,readable;static Proposals props;
 public static Shader GlassShaderR10;public static Shader Shader;public static Texture2D Albedo,Metal;
 public static void Bind(Shader shader,Texture2D albedo,Texture2D metal){Shader=shader;Albedo=albedo;Metal=metal;if(!Shader||!Albedo||!Metal)throw new Exception("City2 serialized bindings missing");}
 static void Load(){if(geometry!=null)return;geometry=JsonUtility.FromJson<C2.CityDensityPack.Geometry>(Resources.Load<TextAsset>("CityDensityR2/CityGeometryR2Compact").text);dense=JsonUtility.FromJson<C2.CityDensityPack.Layout>(Resources.Load<TextAsset>("CityDensityR2/CityPlacementDense").text);readable=JsonUtility.FromJson<C2.CityDensityPack.Layout>(Resources.Load<TextAsset>("CityDensityR2/CityPlacementReadable").text);props=JsonUtility.FromJson<Proposals>(Resources.Load<TextAsset>("CityDensityR2/CityDestructionProposals").text);geometry=FarBreakablePackR10.MergeGeometry(geometry,Resources.Load<TextAsset>("FarWorldR10/Geometry"));geometry=FarBreakablePackR10.MergeGeometry(geometry,Resources.Load<TextAsset>("RouteR12/Geometry"));geometry.assets=geometry.assets.Concat(JsonUtility.FromJson<C2.CityDensityPack.Geometry>(Resources.Load<TextAsset>("MallAreasR5/Geometry").text).assets).ToArray();props.assets=props.assets.Concat(JsonUtility.FromJson<Proposals>(Resources.Load<TextAsset>("MallAreasR5/Proposals").text).assets).ToArray();props.assets=props.assets.Concat(JsonUtility.FromJson<Proposals>(Resources.Load<TextAsset>("RouteR12/Proposals").text).assets).ToArray();var extra=FarBreakablePackR10.ReadProposals(Resources.Load<TextAsset>("FarWorldR10/Proposals"));props.assets=props.assets.Concat(extra.assets.Select(x=>new Proposal{asset=x.asset,material=x.material,massKgSuggestion=x.massKgSuggestion,normalizedImpulseThresholdSuggestion=x.normalizedImpulseThresholdSuggestion,maxPostBreakSpeedFractionSuggestion=x.maxPostBreakSpeedFractionSuggestion,shards=x.shards.Select(y=>new Shard{shard=y.shard,center=y.center,size=y.size,massKgSuggestion=y.massKgSuggestion}).ToArray()})).ToArray();
 geometry.assets=geometry.assets.Concat(MallDensityProto.Geometry()).ToArray();props.assets=props.assets.Concat(MallDensityProto.Props()).ToArray();}

#if UNITY_EDITOR
 public static void ReviewSetLayout(string json){Load();dense=JsonUtility.FromJson<C2.CityDensityPack.Layout>(json);}
#endif
 public static Proposal Prop(string asset){Load();return props.assets.First(p=>p.asset==asset);}
 public static C2.CityDensityPack.Asset Asset(string asset){Load();return geometry.assets.First(a=>a.id==asset);}
 public static GameObject Build(int mode,bool contacts,bool readableWood=false,ContactVisualTemplateR15 template=null){Load();bool useCore=UseCoreLayout;
#if UNITY_EDITOR
 useCore &= !ReviewUseDenseLayout;
#endif
 if(useCore&&core==null)core=JsonUtility.FromJson<C2.CityDensityPack.Layout>(Resources.Load<TextAsset>("CityDensityR2/CityPlacementCore").text);if(UseAtriumRoute&&atrium==null)atrium=JsonUtility.FromJson<C2.CityDensityPack.Layout>(Resources.Load<TextAsset>("CityDensityR2/CityPlacementAtrium").text);var input=mode==1?readable:useCore?(UseAtriumRoute?atrium:core):dense;if(UseFarWorldR10&&farWorldR10==null)farWorldR10=JsonUtility.FromJson<C2.CityDensityPack.Layout>(Resources.Load<TextAsset>("FarWorldR10/Placements").text);if(UseRouteBlockoutR11&&farRouteR11==null)farRouteR11=JsonUtility.FromJson<C2.CityDensityPack.Layout>(Resources.Load<TextAsset>("FarWorldR10/PlacementsR11").text);if(UseProgressionR12&&routeR12==null)routeR12=JsonUtility.FromJson<C2.CityDensityPack.Layout>(Resources.Load<TextAsset>("RouteR12/Placements").text);var chosenFar=UseProgressionR12?routeR12:UseRouteBlockoutR11?farRouteR11:farWorldR10;var allInstances=UseFarWorldR10&&mode==2&&useCore?input.instances.Concat(chosenFar.instances).ToArray():input.instances;if(UseRouteR29&&useCore&&UseFarWorldR10&&mode==2){if(routeR29==null)routeR29=JsonUtility.FromJson<C2.CityDensityPack.Layout>(Resources.Load<TextAsset>("RouteR29/Placements").text);allInstances=allInstances.Concat(routeR29.instances).ToArray();}if(useCore&&mode==2){allInstances=WorldEscalationR8.Layout(allInstances);allInstances=MallAreasR5.Layout(allInstances);allInstances=MallDensityProto.Layout(allInstances);allInstances=NeonDensity.Layout(allInstances);}var layout=new C2.CityDensityPack.Layout{revision=input.revision,instances=allInstances.Where(x=>x.breakable==contacts&&(!UseWorldArtR9||contacts||x.band!="mid")).ToArray()};var used=layout.instances.Select(x=>x.asset).Distinct().ToArray();var data=new C2.CityDensityPack.Geometry{revision=geometry.revision,palette=geometry.palette,assets=geometry.assets.Where(x=>used.Contains(x.id)).ToArray()};// Keep only broken-metal display triangles readable for camera visibility, in both ON/OFF variants.
 var readableMetal=contacts?new HashSet<string>(used.Where(id=>readableWood||(!id.Contains("crate")&&id!="market_stall"&&id!="street_bench"&&id!="street_awning"))):null;if(contacts&&template!=null){var key=JsonUtility.ToJson(layout)+"|"+readableWood+"|"+UseWorldArtR9+"|"+SectionWorldArtR16.Enabled+"|"+MallAreasR5.Enabled+"|"+GiftStoreR7.Enabled+"|"+(Shader?Shader.GetInstanceID():0)+"|"+(GlassShaderR10?GlassShaderR10.GetInstanceID():0)+"|"+(Albedo?Albedo.GetInstanceID():0)+"|"+(Metal?Metal.GetInstanceID():0);return template.Spawn(key,geometry,()=>Build(mode,contacts,readableWood));}var built=C2.CityDensityPack.Build(data,layout,Albedo,Metal,Shader,C2.CityDensityPack.Detail.Balanced,true,readableMetal);if(UseWorldArtR9)foreach(var visual in built.GetComponentsInChildren<C2.CityVisualBreakable>()){if(!visual.assetId.StartsWith("mall_r5_"))DistrictWorldArtR9.ApplyBreakable(visual,Shader);FarBreakablePackR10.ApplyTransparentGlass(visual,Asset(visual.assetId),GlassShaderR10);}if(SectionWorldArtR16.Enabled){SectionWorldArtR16.ApplyBreakables(built);MallModelPackR18.ApplyToRoot(built);MallAreasR5.Apply(built);}NeonDensity.ApplyAppearance(built);BlenderFamilyOverride.Apply(built);return built;}
 public static Vector3 V(float[] a){return new Vector3(a[0],a[1],a[2]);}
 public static Bounds Bounds(C2.CityDensityPack.Piece p){var b=new Bounds(new Vector3(p.v[0],p.v[1],p.v[2]),Vector3.zero);for(int i=3;i<p.v.Length;i+=3)b.Encapsulate(new Vector3(p.v[i],p.v[i+1],p.v[i+2]));return b;}
}
